//go:build amd64 && !purego
// +build amd64,!purego

#include "textflag.h"

#define LOAD_LE_WORD(OFF, STK) \
	MOVL	OFF(SI), AX; \
	MOVL	AX, STK(SP)

#define STORE_LE_WORD(STK, OFF) \
	MOVL	STK(SP), AX; \
	MOVL	AX, OFF(DI)

#define SBOX_POS(SBOX, POSMASK, NIBS, ACC, TMP) \
	VPSHUFB	NIBS, SBOX, TMP; \
	VPAND	POSMASK(SB), TMP, TMP; \
	VPOR	TMP, ACC, ACC

#define SBOX_POS_HI(SBOX, POSMASK, NIBS, ACC, TMP) \
	VPSHUFB	NIBS, SBOX, TMP; \
	VPSLLW	$4, TMP, TMP; \
	VPAND	POSMASK(SB), TMP, TMP; \
	VPOR	TMP, ACC, ACC

#define SUBST(IN, OUT, LOW, HIGH, TMP) \
	VMOVDQU	IN, LOW; \
	VPAND	Y15, LOW, LOW; \
	VMOVDQU	IN, HIGH; \
	VPSRLW	$4, HIGH, HIGH; \
	VPAND	Y15, HIGH, HIGH; \
	VPXOR	OUT, OUT, OUT; \
	SBOX_POS(Y7, ·simdPos0Mask, LOW, OUT, TMP); \
	SBOX_POS(Y9, ·simdPos1Mask, LOW, OUT, TMP); \
	SBOX_POS(Y11, ·simdPos2Mask, LOW, OUT, TMP); \
	SBOX_POS(Y13, ·simdPos3Mask, LOW, OUT, TMP); \
	SBOX_POS_HI(Y8, ·simdPos0Mask, HIGH, OUT, TMP); \
	SBOX_POS_HI(Y10, ·simdPos1Mask, HIGH, OUT, TMP); \
	SBOX_POS_HI(Y12, ·simdPos2Mask, HIGH, OUT, TMP); \
	SBOX_POS_HI(Y14, ·simdPos3Mask, HIGH, OUT, TMP)

TEXT ·cpuid(SB), NOSPLIT, $0-24
	MOVL	eaxArg+0(FP), AX
	MOVL	ecxArg+4(FP), CX
	CPUID
	MOVL	AX, eax+8(FP)
	MOVL	BX, ebx+12(FP)
	MOVL	CX, ecx+16(FP)
	MOVL	DX, edx+20(FP)
	RET

TEXT ·xgetbv(SB), NOSPLIT, $0-16
	MOVL	index+0(FP), CX
	XGETBV
	MOVL	AX, eax+8(FP)
	MOVL	DX, edx+12(FP)
	RET

TEXT ·cryptBlocksAVX2(SB), NOSPLIT, $64-40
	MOVQ	dst+0(FP), DI
	MOVQ	src+8(FP), SI
	MOVQ	n+16(FP), R12
	MOVQ	keys+24(FP), R8
	MOVQ	sbox+32(FP), R13
	VMOVDQU	·simdNibbleMask(SB), Y15
	VMOVDQU	0(R13), Y7
	VMOVDQU	32(R13), Y8
	VMOVDQU	64(R13), Y9
	VMOVDQU	96(R13), Y10
	VMOVDQU	128(R13), Y11
	VMOVDQU	160(R13), Y12
	VMOVDQU	192(R13), Y13
	VMOVDQU	224(R13), Y14

avx2Loop:
	VMOVDQU	0(SI), Y2
	VMOVDQU	32(SI), Y3
	VMOVDQU	·simdPermN1(SB), Y4
	VMOVDQU	·simdPermN2(SB), Y5
	VPERMD	Y2, Y4, Y0
	VPERMD	Y3, Y4, Y6
	VPERM2I128	$0x20, Y6, Y0, Y0
	VPERMD	Y2, Y5, Y1
	VPERMD	Y3, Y5, Y6
	VPERM2I128	$0x20, Y6, Y1, Y1
	MOVQ	R8, R9
	MOVQ	$32, R10

avx2Round:
	VPBROADCASTD	(R9), Y2
	VPADDD	Y2, Y0, Y3
	SUBST(Y3, Y4, Y5, Y6, Y2)
	VPSLLD	$11, Y4, Y5
	VPSRLD	$21, Y4, Y4
	VPOR	Y5, Y4, Y4
	VPXOR	Y1, Y4, Y4
	VMOVDQU	Y0, Y1
	VMOVDQU	Y4, Y0
	ADDQ	$4, R9
	SUBQ	$1, R10
	JNZ	avx2Round

	VPUNPCKLDQ	Y0, Y1, Y2
	VPUNPCKHDQ	Y0, Y1, Y3
	VPERM2I128	$0x20, Y3, Y2, Y4
	VPERM2I128	$0x31, Y3, Y2, Y5
	VMOVDQU	Y4, 0(DI)
	VMOVDQU	Y5, 32(DI)

	ADDQ	$64, SI
	ADDQ	$64, DI
	SUBQ	$64, R12
	JNZ	avx2Loop
	VZEROUPPER
	RET

